  if (t === "" || t === "None" || t === "null" || t === "undefined" || t === "NaN") { return ""; }
  return t;
}
function nhMyName(d) { return nhMyG(d, "name"); }
function nhMyAuthor(d) { return nhMyG(d, "author"); }
function nhMyCover(d) {
  var c = nhMyG(d, "coverUrl");
  if (c !== "" && c.indexOf("/") === 0) { c = "https://moyue.app" + c; }
  return c;
}
function nhMyKind(d) {
  // ⚠ 只返回【作品分类】（状态·分类·字数）——【不要拼平台名】。
  //   本源其它平台的 kind 惯例是作品属性（「已完结 · 51万热度 · 在读」），
  //   平台名由详情页 intro 的「源站：xxx」体现。
  return nhMyG(d, "kind");
}
// 站方 detail 不返回字数 → 不编（空）；但 kind 里若带了「xx万字」就顺手取出来
function nhMyWords(d) {
  var s = nhMyG(d, "kind") + " " + nhMyG(d, "intro");
  var m = s.match(/([\d.]+)\s*万字/);
