// 从锚文本里取干净书名：先剥标签 → 再试 alt= → 再试 title=
function nhFbName(inner) {
  var raw = String(inner == null ? "" : inner);
  var t = raw.replace(/<[^>]+>/g, " ").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&")
             .replace(/&#\d+;/g, " ").replace(/\s+/g, " ").trim();
  if (t !== "") { return t; }
  var m = raw.match(/alt="([^"]{1,80})"/);
  if (m) { t = String(m[1]).trim(); if (t !== "") { return t; } }
  var m2 = raw.match(/title="([^"]{1,80})"/);
  if (m2) { t = String(m2[1]).trim(); if (t !== "") { return t; } }
  return "";
}
// 通用兜底：按【书链 URL 形态】抽书（与容器 class 无关）
//   ⚠ 只在主解析 0 条时调用；返回 7 段协议行（url|||name|||…其余留空）
function nhFallbackBooks(body, meta) {
  var out = [];
  if (!meta || !meta.r || meta.r.length === 0) { return out; }
  var s = String(body == null ? "" : body);
  var regs = [];
  for (var i = 0; i < meta.r.length; i++) {
    try { regs.push(new RegExp(meta.r[i], "g")); } catch (e) { }
  }
  var ms = nhMatchAll(s, regs);
  if (ms.length === 0) { return out; }
  var byUrl = {}, order = [], seen = {};
  for (var j = 0; j < ms.length; j++) {
    var url = String(ms[j][1] || "");
    if (url === "") { continue; }
    var abs = (/^https?:/i.test(url)) ? url : (String(meta.b).replace(/\/$/, "") + url);
    // ⚠⚠ 必须用 hasOwnProperty 判重：byUrl[abs] 初始是空串（falsy），
    //   用 if (!byUrl[abs]) 判 ⇒ 每本书会被登记两次（封面 a + 标题 a）⇒ 出双倍条目
    if (!Object.prototype.hasOwnProperty.call(seen, abs)) {
      seen[abs] = 1; byUrl[abs] = ""; order.push(abs);
    }
    var nm = nhFbName(ms[j][2]);
    if (nm !== "" && byUrl[abs] === "") { byUrl[abs] = nm; }
  }
  for (var k = 0; k < order.length; k++) {
    var u = order[k];
    // 7 段：url|||name|||author|||cover|||intro|||kind|||tag（缺的留空，不编）
    out.push(u + "|||" + byUrl[u] + "|||" + "" + "|||" + "" + "|||" + "" + "|||" + "" + "|||" + "");
  }
  return out;
}

// ── 结构哨兵账本（零额外请求）────────────────────────────────────────
//   键 = 平台名；值 = { n: 本次条数, fb: 是否走了兜底, mx: 历史最好条数 }
function nhSentinelNote(platName, n, usedFallback) {
  try {
    if (!platName) { return; }
    var cnt = parseInt(String(n || 0), 10) || 0;
    var fb = usedFallback ? 1 : 0;
    var led = {};
    try { led = JSON.parse(String(source.get("nhSentinel") || "{}")) || {}; } catch (e) { led = {}; }
    var prev = led[platName] || {};
    var mx = parseInt(String(prev.mx || 0), 10) || 0;
    if (cnt > mx) { mx = cnt; }
    // ⚠ 内容没变就别写：发现页刷新很频繁 ⇒ 每次都 source.put 会拖慢 App
    if (parseInt(String(prev.n || -1), 10) === cnt && parseInt(String(prev.fb || 0), 10) === fb
        && parseInt(String(prev.mx || 0), 10) === mx) { return; }
    led[platName] = { "n": cnt, "fb": fb, "mx": mx, "t": Date.now() };
    try { source.put("nhSentinel", JSON.stringify(led)); } catch (e2) { }
  } catch (e3) { }
}
// 读账本 + 比基线 ⇒ 出报告（登录菜单「🧭 结构体检」用）
function nhSentinelReport() {
  var led = {};
  try { led = JSON.parse(String(source.get("nhSentinel") || "{}")) || {}; } catch (e) { led = {}; }
  var L = [], bad = 0, seen = 0;
  for (var i = 0; i < NH_PLAT_META.length; i++) {
    var meta = NH_PLAT_META[i];
    var rec = led[meta.n];
    if (!rec) { continue; }
    seen++;
    var n = parseInt(String(rec.n || 0), 10) || 0;
    var mx = parseInt(String(rec.mx || 0), 10) || 0;
    var tag = "";
    if (n === 0) {
      tag = "🔴 0 条（站方很可能改了结构）"; bad++;
    } else if (rec.fb) {
      tag = "🟡 " + n + " 本（主解析失配，靠【备用链】兜住的）"; bad++;
    } else if (n < meta.f) {
      tag = "🟠 " + n + " 本（基线至少 " + meta.f + " 本）"; bad++;
    } else {
      tag = "🟢 " + n + " 本";
    }
    if (mx > n && n > 0) { tag += "（最好过 " + mx + "）"; }
    L.push("　" + meta.n + "：" + tag);
  }
  var head = "【结构体检】";
  if (seen === 0) { head += "还没有数据（先在发现页翻一遍）"; }
  else if (bad === 0) { head += "全部正常（" + seen + " 个平台）"; }
  else { head += (bad + " 个平台异常（共 " + seen + " 个）"); }
  var tail = "";
  if (bad > 0) {
    tail = "\n说明：🔴 = 站方改了页面结构；🟡 = 主解析失配、已由备用链顶上（书还能读，"
      + "但作者/封面/简介会缺）；🟠 = 条数偏少。把异常那几行发给源作者即可。";
  }
  return head + "\n" + L.join("\n") + tail;
}
