// ═══ UAA 自动续期：状态与失败原因（2026-11-04 真机修）═══
//   真机反馈「UAA 也没有自动续签」⇒ 光有功能不够，【为什么没续上】必须看得见。
var NH_UAA_RENEW_ERR = "";    // 上一次续期失败的原因（人话）
function nhUaaRenewFail(reason) {
  var r = String(reason == null ? "" : reason);
  try { NH_UAA_RENEW_ERR = r; } catch (e) { }
  try { source.put("nhUaaRenewErr", r); } catch (e2) { }
}
function nhUaaRenewClear() {
  try { NH_UAA_RENEW_ERR = ""; } catch (e) { }
  try { source.put("nhUaaRenewErr", ""); } catch (e2) { }
}
// 自动续期现状（一句话）
function nhUaaRenewState() {
  var on = nhUaaAutoOn();
  var pws = nhUaaAutoPw();
  var err = "";
  try { err = String(source.get("nhUaaRenewErr") || ""); } catch (e) { }
  var s = "";
  if (!on) { s = "自动续期：🔴 关着"; }
  else if (pws.length < 3) {
    s = "自动续期：🔴 开着但【没填三个口令】⇒ 过期了不会自动重领"
        + "（登录页 → 🦄 UAA → 「UAA 自动续期口令」）";
  } else {
    var _src2 = "";
    try { _src2 = nhUaaPwSrc(); } catch (e4) { _src2 = ""; }
    s = "自动续期：🟢 开着（三个口令已填）" + (_src2 !== "" ? ("\n口令来源：" + _src2) : "");
  }
  if (err !== "") { s += "\n上次续期失败：" + err; }
  else if (on && pws.length >= 3) {
    s += "\n令牌：" + nhUaaDdlText();
  }
  return s;
}

// 重新签名一个 UAA URL（剥掉旧的 ,{headers} 后缀 ⇒ 用当前令牌重新签）
//   ⚠ 场景：发现页点分类后的书列表，URL 里带的是【旧令牌】的签名
//     ⇒ 续期拿到新令牌后，必须重新签，否则重发的还是旧令牌 ⇒ 照样 401
function nhUaaResign(u) {
  var s = String(u == null ? "" : u);
  var i = s.indexOf(",{");
  if (i >= 0) { s = s.slice(0, i); }
  if (s === "") { return ""; }
  try { return nhUaaSign(s); } catch (e) { return s; }
}

// 把站方下发的【分类 url】算成可直接请求的地址
//   · 可能是 @js:getApiUrl('...', {…page…}) 片段 ⇒ 求值
//   · 可能是相对路径 ⇒ 补 API 域
//   · 缺鉴权 ⇒ 补 ,{headers} 签名（Bearer + x-android-id）
function nhUaaEntryUrl(u) {
  var s = String(u == null ? "" : u).trim();
  if (s === "") { return ""; }
  if (s.indexOf("@js:") === 0) {
    try { s = String(eval(s.substring(4))); } catch (e) { return ""; }
    s = String(s == null ? "" : s).trim();
  }
  if (s.indexOf("http") !== 0) {
    if (s.indexOf("/") === 0) { s = NH_UAA_API + s; } else { return ""; }
  }
  if (s.indexOf("uaa1234.com") >= 0 && s.indexOf(",{") < 0 && s.indexOf("token=") < 0) {
    try { s = nhUaaSign(s); } catch (e2) { }
  }
  return s;
}

// ═══ 🍑西瓜书屋（xiguashuwu2）换站 + CF 工具 ═══
//   ⚠ 与原源《🍑西瓜书屋[可换备用站]》的唯一差别：
//     原源用 source.getVariable() 存【当前域名】，而 NovelHub 的 getVariable()
//     存的是【发现页筛选 JSON】⇒ 直接搬会把筛选 JSON 当域名用 ⇒ 换站功能直接坏
//   ⇒ 改用独立源变量 nhXgHost（xgSet 写它、xgHost 读它；
//     读不到再退回 getVariable，兼容从原源迁移过来的旧值）
//   其余函数体与按钮文案【原封不动】
function xgHosts(){
  return ['https://www.xiguashuwu2.com','https://www.xiguashuwu.net','http://www.xiguashuwu.com'];
}
function xgHost(sv){
  var h="";
  try{ h=String(sv.get("nhXgHost")||""); }catch(e){ h=""; }
  if(h===""||h==="null"||h==="undefined"){
    try{ h=String(sv.getVariable()||''); }catch(e2){ h=""; }
    if(h&&h.charAt(0)==="{"){ h=""; }
  }
  var hs=xgHosts();
  for(var i=0;i<hs.length;i++){if(h==hs[i]){return hs[i];}}
  return hs[0];
}
function xgSet(sv,u){
  try{ sv.put("nhXgHost",u); }catch(e0){}
  try{ cookie.setCookie(u,'nginx_waf_passed=1'); }catch(e1){}
  if(u.indexOf('xiguashuwu2')>=0){
    java.toast('已切换主站(需过CF验证,通过一次长期有效)');
  }else{
    java.toast('已切换备用站并写入免验证Cookie');
  }
  return u;
}
function FQ_xg_now(java,source){java.toast('当前网址：'+xgHost(source)+'（点击切换按钮换站）');}
function FQ_xg_swap(java,source){
  var hs=xgHosts();
  var cur=xgHost(source);
  var k=0;
  for(var i=0;i<hs.length;i++){if(hs[i]==cur){k=(i+1)%hs.length;break;}}
  xgSet(source,hs[k]);
}
function FQ_xg_pick0(java,source){xgSet(source,xgHosts()[0]);}
function FQ_xg_pick2(java,source){xgSet(source,xgHosts()[1]);}
function FQ_xg_check(java,source){
  var u=xgHost(source);
  try{
    var r=String(java.ajax(u)||'');
    if(r.indexOf('安全验证')>=0){
      java.toast('站点在线，但缺免验证Cookie，点【切换网址】重新选一次即可修复');
    }else if(r.indexOf('Just a moment')>=0){
      java.toast('主站CF盾拦截中：正常搜索一次会自动弹出验证');
    }else if(r.length<500){
      java.toast('网站响应异常('+r.length+'字符)，站点可能已更换域名');
    }else{
      java.toast('站点连接正常（'+u+'）');
    }
  }catch(e){java.toast('检查失败：'+e)}
}
// ── 搜索开关（西瓜默认关 / 91Hub 默认开）────────────────────────────
//   ⚠ 为何西瓜默认关：站方限频 3 秒/次，主站搜索撞 CF 盾，备用站会挂 30 秒；
//     栖阅 java.ajax 无内置超时 ⇒ 一个口挂住 ⇒ 整条搜索规则被掐掉 ⇒ 一条都搜不到。
function toggleXgSearch(java,source){
  // ⚠ 统一语义（2026-11-08）：【1 = 开】，读不到值时用注册表给的默认值（西瓜=0=默认关）。
  //   与 toggleH91Search 现在是同一套写法，不再一个 1=开 一个 0=开。
  var v = String(source.get("nhXgSearch")||"0");
  var nv = (v === "1") ? "0" : "1";
  source.put("nhXgSearch", nv);
  java.toast(nv === "1" ? "✅ 已开启：搜索时带上西瓜书屋（站方限频，别连续搜）" : "⛔ 已关闭：搜索不带上网瓜书屋");
}
function toggleH91Search(java,source){
  // ⚠ 统一语义（2026-11-08）：【1 = 开】，读不到值时用注册表给的默认值（91Hub=1=默认开）。
  //   ⚠ 存量兼容：老实现是「!== "0"」⇒ 空值=开、"0"=关、"1"=开；
  //     新写法是「=== "1"」⇒ 空值按默认 1=开、"0"=关、"1"=开 ⇒ 行为逐值一致。
  var v = String(source.get("nhH91Search")||"1");
  var nv = (v === "1") ? "0" : "1";
  source.put("nhH91Search", nv);
  java.toast(nv === "1" ? "✅ 已开启：搜索时带上 91Hub" : "⛔ 已关闭：搜索不带上 91Hub");
}
function FQ_xg_cf(java,source){
  try{
    java.startBrowserAwait(xgHost(source)+'/search/','西瓜书屋·人机验证');
    java.toast('验证流程结束，若搜索仍失败请稍后重试');
  }catch(e){java.toast('未完成：'+e)}
}

// ═══ 91Hub 封面解码（站方列表/详情给的 og:image 都是【编码 URL】）═══
//   形如 https://xi.dzuxta.cn/upload_01/upload/20250711/2025071112020980787.jpeg?auth_key=…
//   ⇒ 后面那截是 base64 ⇒ 解出来当路径用 ⇒ https://91hubs.com/social-cover/<decoded>.jpeg
//   ⚠ 不是 base64 就不用解（原样返回），别乱解。
function nh91Cover(u) {
  var v = String(u == null ? "" : u);
  if (v === "") { return ""; }
  var m = v.match(/https:\/\/xi\.dzuxta\.cn([^?]+)/);
  if (!m) { return v; }
  var p = m[1];
  var K = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  var o = "";
  for (var i = 0; i < p.length; i += 3) {
    var a = p.charCodeAt(i), b = p.charCodeAt(i + 1), c = p.charCodeAt(i + 2);
    o += K[a >> 2] + K[((a & 3) << 4) | ((b || 0) >> 4)];
    o += (isNaN(b) ? "=" : K[((b & 15) << 2) | ((c || 0) >> 6)]);
    o += (isNaN(c) ? "=" : K[c & 63]);
  }
  var em = p.match(/\.(jpe?g|png|gif|webp)$/i);
  var ext = em ? em[1].toLowerCase() : "jpeg";
  if (ext === "jpg") { ext = "jpeg"; }
  return "https://91hubs.com/social-cover/" + o.replace(/=+$/, "") + "." + ext;
}

// ═══ 详情页「结构化载荷」：书链里带一份小 JSON（base64url）═══
//   形如：https://www.xiguashuwu2.com/book/222825/iszip/0/?_nh=eyJpIjoieCJ9
//   用途：① 详情页直接拿到平台标识 + 书号（零额外请求）
//         ② 书链自带站方标识 ⇒ 详情/目录/正文不用只靠 host 猜（抗改版）
//   ⚠ 站方实测【忽略未知 query 参数】（加与不加都 200、体积一致）
function nhPayloadEnc(o) {
  try {
    var b = String(java.base64Encode(JSON.stringify(o)) || "");
    return b.replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  } catch (e) { return ""; }
}
function nhPayloadDec(u) {
  var m = String(u == null ? "" : u).match(/[?&]_nh=([A-Za-z0-9_-]+)/);
  if (!m) { return null; }
  try {
    var t = m[1].replace(/-/g, "+").replace(/_/g, "/");
    while (t.length % 4) { t += "="; }
    var s = String(java.base64Decode(t) || "");
    return s ? (JSON.parse(s) || null) : null;
  } catch (e) { return null; }
}

