// ⚠ 登录按钮路径里 java 是 SourceLoginJsExtensions，不是 JsExtensions。
//   没有 toast / longToast，只有 copyText / refreshExplore / showBrowser 等。
// ⚠ 这一行就是「点登录没有任何反应」的元凶（2026-10-08 修）：
//   登录按钮的 JS 上下文里 java 是 SourceLoginJsExtensions，只有
//   upUiData / reUiView / refreshExplore / copyText / clearTtsCache / showBrowser
//   ——【没有 toast】。原来 `java.toast(msg)` 抛异常被 catch 吞掉，消息就没了；
//   更糟的是紧接着的 `java.reLoginView()` 会把登录界面【整个重绘一遍】，
//   连同状态行一起重置回默认值 —— 就算网页真的打开了，你也看不到任何提示。
// 现在：直接写进 loginUi 第 0 行「📌 当前状态（点击复制）」，用户一定看得见。
function nhSay(msg) {
    msg = String(msg == null ? "" : msg);
    // ⚠ 顺序不能换，而且【三条路都得留】（2026-10-08 被我删过 toast + reLoginView，
    //   用户实机反馈「检测按钮点了没反应」—— 提示没了才发现）：
    //   ① reLoginView 放【最前】。它会把登录界面整个重绘、把状态行刷回默认值，
    //      放后面会把刚写的内容又擦掉。
    try { java.reLoginView(); } catch (e) { }
    // ② 写状态行。文本行在 Legado 里是【输入框】(ItemSourceEditBinding)，
    //      handleUpUiData 对它走 setText 分支，能写进去。
    try { java.upUiData({ "📌 当前状态（点击复制）": msg }); } catch (e) { }
    // ③ toast：NovelReader 分支【有】这个方法（用户实机见过它的提示）；
    //    stock Legado 的 SourceLoginJsExtensions 没有 → 抛异常被吞，不影响其它两条。
    try { java.toast(msg); } catch (e) { }
    try { java.copyText(msg); } catch (e) { }
}

// 🔑 状态存【源级变量 source.setVariable】，不是 cookie。
//    大灰狼聚合源（支持苹果/栖阅）就是这么干的：登录按钮 setVariable + java.refreshExplore()，
//    exploreUrl 用 <js> 运行时读回来，分类列表因此能整体重建。
function nhSet(x) {
