        var _h2 = nhSafeHidden();
        for (var _q = 0; _q < _h2.length; _q++) {
          if (String(x) === _h2[_q]) {
            nhSay("🔞 「" + nhName(x) + "」已被 18禁开关隐藏" + String.fromCharCode(10)
                + "想看的话，先点顶部「🔞 18禁平台」把开关关掉。");
            return;
          }
        }
      }
    } catch (e) { }
    var ok = false;
    // 与筛选行共用同一个 JSON 结构：{src, gender, status, sort}
    // 只改 src，保留用户已选的其它筛选项
    try {
        // ⚠ 默认值必须跟 nhSetF 那份【一致】——少了 kind 的话，用登录页切一次平台
        //   就把「📚类型」冲没了（下次读 NH_D["kind"] 是 undefined，类型筛选静默失效）。
        var d = { src: "全部", gender: "全部", status: "不限", sort: "最热", line: "自动", kind: "🌐全部" };
        var raw = String(source.getVariable() || "").trim();
        if (raw !== "") { var o = JSON.parse(raw); if (o && typeof o === "object") { d = o; } }
        d.src = String(x);
        source.setVariable(JSON.stringify(d)); ok = true;
        // ⚠ 2026-11-08 平台切换统一：登录上下文的 infoMap 里【没有】「平台」这一项
        //   （那是发现页筛选行专用的 map）⇒ 从这里切台后，发现页下拉框还停在旧平台
        //   ⇒ exploreUrl 的自愈块会把切换回退 ⇒ 切不过去。
        //   ⇒ 写一次性标记，exploreUrl 见到就以本变量为准（不回退），并消费掉标记。
        try { source.put("nhPlatSwitch", String(x)); } catch (eSw) { }
        // ⭐ 2026-11-08 切台修复：写诊断（书源变量里一眼能看见切到哪、走哪条路）
        try { source.put("nhPlatLog", "菜单切台→" + String(x)); } catch (eLg) { }
    } catch (e) { }
    // ── [2026-11-12] 别再自称「已刷新」──
    //   原来只判 java.refreshExplore() 没抛异常就算成功，可它在栖阅 iOS 上是【空转】：
    //   不抛异常，但页面纹丝不动。用户看到"已刷新"却什么都没变 → 以为坏了。
    //   现在如实说：请下拉刷新。这是既有实测结论（试过 5 种刷新 API 全无效）。
    // ── 只调一个，然后结束 ──
    //   逆向文档（栖阅 2027.01.01）确认 java.refreshExplore 存在；同族的
    //   java.refreshTocUrl() 在二进制里字面写着 (no-op)，别信"多调几个总有一个管用"。
    //   而且连调多个会：第一个触发重建 → 后面几个还在往【已销毁的 JS 上下文】写
    //   → 把正在执行的回调打死 → 表现就是"全空转"（今天实测栽过）。
    // ── 2026-11-08 切台修复：先清发现页分类缓存，再触发重绘 ──
    //   source.refreshExplore 在栖阅 = 「清发现页分类缓存」⇒ 回发现页时会重跑 exploreUrl
    //   ⇒ 切过去的平台能真正显示出来（登录上下文可能没有这个 API ⇒ typeof 守卫，无则跳过）。
    //   ⚠ 顺序是安全边界：java.refreshExplore 放【最后一句】——
    //     触发重建之后再往 JS 上下文写，会把正在执行的回调打死（表现「全空转」）。
    try { if (typeof source.refreshExplore === "function") { source.refreshExplore(); } } catch (eRs) { }
    try { java.refreshExplore(); } catch (e) { }
    if (ok) {
