// ─────────────────────────────────────────────────────────────
// 🔑 站方登录：弹内置浏览器去登录页，登录完回 App 刷新即可。
//    登录菜单 java 桥只有 6 个方法：upUiData / reUiView / refreshExplore /
//    copyText / clearTtsCache / showBrowser（【没有】toast）。
function nhOpenLogin(url, title) {
    var err = "";
    // ⚠⚠ 为什么不能直接 startBrowser/showBrowser（2026-10-08 实机截图定位）：
    //   站方对 `X-Requested-With: XMLHttpRequest` 会返回【JSON 字符串】而不是 HTML ——
    //   实测带该头 4322B（开头带 \"、正文 \" 和 \r\n 全转义），不带该头 3505B 正常 HTML。
    //   而 startBrowser / showBrowser 都是【带书源 header】加载的，我们的 header 里正好有这个
    //   （爱丽丝正文必须靠它，不然返 SEO 空壳页），于是登录页被当成 AJAX 请求，
    //   WebView 渲染成一坨带转义的纯文本 —— 就是你截图里那个。
    //
    // 修法：自己抓一份【不带 XHR 头】的 HTML，直接塞进 showBrowser。
    //   url,{"headers":…} 是【替换】源级 header 的（AnalyzeUrl 第 139 行
    //   `headerMapF ?: source?.getHeaderMap()`，?= 短路，右边根本不会求值），能干净绕开。
    var _ua = "Mozilla/5.0 (Linux; Android 12) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/96.0.4664.104 Mobile Safari/537.36";
    // ⚠ 逗号前【不要留空格】：AnalyzeUrl 的 paramPattern 是 \\s*,\\s*(?=\\{)，
    //   它按逗号位置切 baseUrl，前面那个空格会被留在 URL 尾巴上 → 地址变脏。
    var _opt = '{"headers":{"User-Agent":"' + _ua + '","Accept":"text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8"}}';
    var html = "";
    try {
        html = String(java.ajax(url + "," + _opt) || "");
    } catch (e) {
        // ⚠ 不要把异常原文回显给用户：里面常带着带 ,{headers} 的脏 URL，
        //   用户复制走的地址就是错的（2026-10-08 实机反馈「网址不对」）。
        err = "取登录页失败 ";
    }
    // 兜底：万一站方仍然裹了 JSON，把最外层引号和转义剥掉
    if (html.length > 1 && html.charAt(0) === '"' && html.charAt(html.length - 1) === '"') {
        try { html = String(JSON.parse(html)); } catch (e2) { }
    }
    try { java.showBrowser(url, html); return ""; } catch (e3) { err = err + "showBrowser(" + e3 + ") "; }
    try { java.startBrowser(url, title || "登录"); return ""; } catch (e4) { err = err + "startBrowser(" + e4 + ")"; }
    return "打不开浏览器：" + err;
}

