  try { resp = String(java.ajax(srv + "/login_api," + opt)); } catch (e) { }
  var data = null;
  try { data = JSON.parse(resp); } catch (e) { }
  if (data && data.code === 0 && data.key) {
    // ⚠⚠ 必须连 deviceId 一起写！大灰狼 /content 认的是
    //    `qttoken=xxx; deviceId=yyy`，缺 deviceId 直接拒（这是我踩过的坑）。
    var _devId = "";
