    if (_devId === "") { try { _devId = String(java.deviceID() || ""); } catch (e) { } }
    if (_devId === "") { _devId = "novelhub"; }
    var ck = "qttoken=" + data.key + "; deviceId=" + _devId + "; device=" + _devId;
    // ⚠ replaceCookie(url, ck) 的 url 必须是【带尾部斜杠的完整地址】，
    //   它靠 url 解析域来存 cookie；"http://1.2.3.4:5006"（无斜杠）会解析失败。
    //   先 replaceCookie（不洗掉已有 cookie），失败再 setCookie 兜底。
    var wrote = 0;
    for (var i = 0; i < DLH_HOSTS.length; i++) {
      var u = DLH_HOSTS[i] + "/";
      var okk = false;
      try { cookie.replaceCookie(u, ck); okk = true; } catch (e) { }
      if (!okk) { try { cookie.setCookie(u, ck); okk = true; } catch (e) { } }
      if (okk) { wrote++; }
    }
    nhSay("大灰狼账号登录成功 ✅ 密钥已写入 " + wrote + "/" + DLH_HOSTS.length
          + " 条线路  ｜接着点「② 登录番茄」");
  } else {
    var why = (data && data.msg) ? data.msg : "网络异常";
    nhSay("大灰狼账号登录失败：" + why);
  }
}

