// ═══════════════════════════════════════════
function nhCookieAny(list, need) {
  for (var i = 0; i < list.length; i++) {
    try {
      var c = String(cookie.getCookie(list[i]) || "");
      if (c !== "" && (!need || c.indexOf(need) >= 0)) { return c; }
    } catch (e) { }
  }
  // ⚠⚠ 2026-10-10 修：原来最后有一句「cookie.getCookie() 不带参数 → 读全部 cookie」兜底。
  //   站点 cookie 是全 App 共用的池子，一兜底就把【别的站】的 cookie 拿来判本站登录态 ——
  //   这就是「禁漫天堂明明没登、检测却说已登录」的元凶。要么查本站，要么承认不知道。
  return "";
}
// ══════════════════════════════════════════════════════════════
// 登录态检测族的【统一 cookie 读取层】（2026-11-02 收敛）
//
// 为什么要有这一层：
//   原来 5 个检测函数各自手写 cookie 读取（11 处）⇒ 同构代码各写各的，
//   每个都是独立的 bug 温床。已踩过两次同一个坑：
//     ① 2026-10-10：有人加「无参 cookie.getCookie() 兜底」⇒ 拿【别的站】的 cookie
//        判本站登录态 ⇒ 禁漫没登却说已登录。
//     ② 2026-11-02：修禁漫时又加了一次无参兜底 ⇒ 把同一个坑挖回来。
//   ⇒ 收敛成下面 3 个具名 helper：
//      · nhCookieAny(domains, need)     【源里已有】严格本站域，永不无参
//      · nhCookieValue(domains, name)  逐域精确取单个 cookie 值
//      · nhAnyCookieNamed(name)         全池按名（仅用于名字特异的，如 sessionid）
//   ⚠ 新增检测只允许用这 3 个，禁止直接调 cookie.getCookie / cookie.getKey。
// ══════════════════════════════════════════════════════════════

// 逐域精确取单个 cookie 值 ⇒ 返回 "name=value"（取不到返回 ""）
//   用途：大灰狼查番茄的 sessionid（它用 cookie.getKey，而不是整串）
function nhCookieValue(domains, name) {
  for (var i = 0; i < domains.length; i++) {
    try {
      var v = String(cookie.getKey(domains[i], name) || "");
      if (v !== "") { return name + "=" + v; }
    } catch (e) { }
  }
  return "";
}

// ⚠⚠ 全 cookie 池里按【名字】找（唯一允许读全部 cookie 的地方）
//   ⚠ cookie 池是全 App 共用的 ⇒ 这里拿到的可能来自【别的站】。
//   ⚠ 所以只允许用于【名字足够特异】的 cookie（如番茄 sessionid），
//     【绝不能】用来判"本站是否登录"—— 那会把别的站的同名 cookie 当本站的。
//   ⚠ 2026-10-10 的教训：禁漫天堂就是被"随手一个无参兜底"害成假「已登录」的。
function nhAnyCookieNamed(name) {
  if (!name) { return ""; }
  try {
    var all = String(cookie.getCookie() || "");
    if (all === "") { return ""; }
    var m = all.match(new RegExp("[\\s\\S]*?" + name + "=[^;\\s]+[\\s\\S]*"));
    return m ? String(m[0]) : "";
  } catch (e) { }
  return "";
}

